                                            for (var i of game.players) {
                                                var cards1 = i.getCards('he');
                                                var storage = player.storage.hdsk_touying;
                                                for (var j of cards1) {
                                                    if (storage.includes(j) && get.subtype(j) == 'equip5') {
                                                        storage.remove(j);
                                                        cards.push(j);
                                                        event.num++;
                                                    }
                                                }
                                            }
                                            if (cards && event.num > 0) {
                                                game.cardsGotoOrdering(cards);
                                                game.log(cards, '被移出了游戏');
                                            }
