                        szdl_lw: {
                            audio: 'ext:Nirvana/audio/贾诩:2',
                            usable: true,
                            enable: 'phaseUse',
                            limited: true,
                            filterTarget(card, player, target) {
                                return target != player;
                            },
                            selectTarget: -1,
                            multitarget: true,
                            multiline: true,
                            content() {
                                'step 0';
                                player.awakenSkill('szdl_lw');
                                event.current = player.next;
                                event.currented = [];
                                ('step 1');
                                event.currented.push(event.current);
                                event.current.addTempClass('target');
                                event.current.addTempSkill('szdl_ws_2');
                                event.current
                                    .chooseToUse(
                                        '乱武:使用一张杀或失去一点体力并令贾诩摸一张牌',
                                        (card) => player.filterCardx(card) && card.name == 'sha',
                                        function (card, player, target) {
                                            if (player == target) return false;
                                            var dist = get.distance(player, target);
                                            if (dist > 1) {
                                                if (
                                                    game.hasPlayer(function (current) {
                                                        return current != player && get.distance(player, current) < dist;
                                                    })
                                                ) {
                                                    return false;
                                                }
                                            }
                                            return lib.filter.filterTarget.apply(this, arguments);
                                        }
                                    )
                                    .set('ai2', function () {
                                        return get.effect_use.apply(this, arguments) + 0.01;
                                    });
                                ('step 2');
                                if (result.bool == false) {
                                    event.current.loseHp();
                                    player.draw();
                                }
                                event.current = event.current.next;
                                if (event.current != player && !event.currented.includes(event.current)) {
                                    event.goto(1);
                                }
                            },
                            ai: {
                                order: 1,
                                result: {
                                    player(player) {
                                        if (lib.config.mode == 'identity' && game.zhu.isZhu && player.identity == 'fan') {
                                            if (game.zhu.hp == 1 && game.zhu.countCards('h') <= 2) return 1;
                                        }
                                        var num = 0;
                                        var players = game.filterPlayer();
                                        for (var i of players) {
                                            var att = get.attitude(player, i);
                                            if (att > 0) att = 1;
                                            if (att < 0) att = -1;
                                            if (i != player && i.hp <= 3) {
                                                if (i.countCards('h') == 0) num += att / i.hp;
                                                else if (i.countCards('h') == 1) num += att / 2 / i.hp;
                                                else if (i.countCards('h') == 2) num += att / 4 / i.hp;
                                            }
                                            if (i.hp == 1) num += att * 1.5;
                                        }
                                        if (player.hp == 1) {
                                            return -num;
                                        }
                                        if (player.hp == 2) {
                                            return -game.players.length / 4 - num;
                                        }
                                        return -game.players.length / 3 - num;
                                    },
                                },
                            },
                            mark: true,
                            intro: {
                                content: 'limited',
                            },
                            init(player, skill) {
                                player.storage[skill] = false;
                            },
                        },
