                        szdl_fencheng: {
                            audio: 'xinfencheng',
                            audioname: ['re_liru'],
                            enable: 'phaseUse',
                            filter(event, player) {
                                return !player.storage.szdl_fencheng;
                            },
                            filterTarget(card, player, target) {
                                return player != target;
                            },
                            limited: true,
                            selectTarget: -1,
                            multitarget: true,
                            multiline: true,
                            mark: true,
                            line: 'fire',
                            content() {
                                'step 0';
                                player.storage.szdl_fencheng = true;
                                player.awakenSkill('szdl_fencheng');
                                event.num = 1;
                                event.current = player.next;
                                ('step 1');
                                event.current.chooseControl('手牌区', '装备区', function (event, player) {
                                    if (player.countCards('h') > player.countCards('e') && player.countCards('e') > 0) return '装备区';
                                    return '手牌区';
                                });
                                ('step 2');
                                if (result.control == '手牌区') {
                                    event.current.chooseToDiscard('h', [1, 3]).set('ai', function (card) {
                                        return 8 - get.value(card);
                                    });
                                    event.goto(3);
                                } else {
                                    var num = event.current.countCards('e');
                                    event.current.chooseToDiscard('e', num, true);
                                    if (num < 2) event.current.damage(2 - num, 'fire');
                                    if (event.current.next != player) {
                                        event.current = event.current.next;
                                        event.goto(1);
                                    } else {
                                        event.finish();
                                    }
                                }
                                ('step 3');
                                if (result.cards?.length) {
                                    var num = 3 - result.cards.length;
                                    event.current.damage(num, 'fire');
                                } else {
                                    event.current.damage(3, 'fire');
                                }
                                if (event.current.next != player) {
                                    event.current = event.current.next;
                                    event.goto(1);
                                } else {
                                    event.finish();
                                }
                            },
                            ai: {
                                order: 1,
                                result: {
                                    player(player) {
                                        var num = 0,
                                            eff = 0,
                                            players = game
                                                .filterPlayer(function (current) {
                                                    return current != player;
                                                })
                                                .sortBySeat(player);
                                        for (var target of players) {
                                            if (get.damageEffect(target, player, target, 'fire') >= 0) {
                                                var num = 0;
                                                continue;
                                            }
                                            var shao = false;
                                            num++;
                                            if (
                                                target.countCards('he', function (card) {
                                                    if (get.type(card) != 'basic') {
                                                        return get.value(card) < 10;
                                                    }
                                                    return get.value(card) < 8;
                                                }) < num
                                            )
                                                shao = true;
                                            if (shao) {
                                                eff -= 4 * (get.realAttitude || get.attitude)(player, target);
                                                var num = 0;
                                            } else eff -= (num * (get.realAttitude || get.attitude)(player, target)) / 4;
                                        }
                                        if (eff < 4) return 0;
                                        return eff;
                                    },
                                },
                            },
                            init(player) {
                                player.storage.szdl_fencheng = false;
                            },
                            intro: {
                                content: 'limited',
                            },
                        },
