                                    for (var i of cards) {
                                        if (i.suit == 'heart') {
                                            target.recover();
                                            player.recover();
                                        }
                                        if (i.suit == 'diamond') {
                                            player.storage.szdl_zhaoren1 = true;
                                            player.draw();
                                            target.draw();
                                        }
                                        if (i.suit == 'club') {
                                            var card = get.cardPile2(function (card) {
                                                return get.tag(card, 'damage');
                                            });
                                            if (card) {
                                                player.gain(card, 'gain2', 'log');
                                            }
                                            event.num = 5;
                                        }
                                        if (i.suit == 'spade') {
                                            player.storage.szdl_zhaoren2 = true;
                                        }
                                    }
                                ('step 1');
                                if (event.num == 5) {
                                    event.num = 0;
                                    var card2 = get.cardPile2(function (card) {
                                        return get.tag(card, 'damage');
                                    });
                                    if (card2) {
                                        event.target.gain(card2, 'gain2', 'log');
                                    }
                                }
                                if (player.storage.szdl_zhaoren1 == true) {
                                    player.storage.szdl_zhaoren1 = false;
                                    var list = [];
                                    if (
                                        lib.filter.cardUsable({ name: 'sha' }, player, event.getParent('chooseToUse')) &&
                                        game.hasPlayer(function (current) {
                                            return player.canUse('sha', current);
                                        })
                                    ) {
                                        list.push(['基本', '', 'sha']);
                                    }
                                    for (var i of lib.inpile_nature) {
                                        if (
                                            lib.filter.cardUsable({ name: 'sha', nature: i }, player, event.getParent('chooseToUse')) &&
                                            game.hasPlayer(function (current) {
                                                return player.canUse({ name: 'sha', nature: i }, current);
                                            })
                                        ) {
                                            list.push(['基本', '', 'sha', i]);
                                        }
                                    }
                                    if (
                                        lib.filter.cardUsable({ name: 'tao' }, player, event.getParent('chooseToUse')) &&
                                        game.hasPlayer(function (current) {
                                            return player.canUse('tao', current);
                                        })
                                    ) {
                                        list.push(['基本', '', 'tao']);
                                    }
                                    if (
                                        lib.filter.cardUsable({ name: 'jiu' }, player, event.getParent('chooseToUse')) &&
                                        game.hasPlayer(function (current) {
                                            return player.canUse('jiu', current);
                                        })
                                    ) {
                                        list.push(['基本', '', 'jiu']);
                                    }
                                    if (list.length) {
                                        player.chooseButton(['是否视为使用一张基本牌？', [list, 'vcard']]).set('ai', function (button) {
                                            var player = _status.event.player;
                                            var card = { name: button.link[2], nature: button.link[3] };
                                            if (card.name == 'tao') {
                                                if (player.hp == 1 || (player.hp == 2 && !player.hasShan()) || player.needsToDiscard()) {
                                                    return 5;
                                                }
                                                return 1;
                                            }
                                            if (card.name == 'sha') {
                                                player.addTempSkill('szdl_huangtian_1', 'useCardAfter');
                                                if (
                                                    game.hasPlayer(function (current) {
                                                        return player.canUse(card, current) && get.effect(current, card, player, player) > 0;
                                                    })
                                                ) {
                                                    if (card.nature == 'fire') return 2.95;
                                                    if (card.nature == 'thunder' || card.nature == 'ice') return 2.92;
                                                    return 2.9;
                                                }
                                                return 0;
                                            }
                                            if (card.name == 'jiu') {
                                                return 0.5;
                                            }
                                            return 0;
                                        });
                                    } else {
                                        event.finish();
                                    }
                                }
                                ('step 2');
                                if (result && result.bool && result.links[0]) {
                                    var card = { name: result.links[0][2], nature: result.links[0][3] };
                                    if (card.name == 'sha') {
                                        player.chooseUseTarget(card, false, 'nodistance');
                                    } else {
                                        player.chooseUseTarget(card, true);
                                    }
                                }
                                ('step 3');
                                if (player.storage.szdl_zhaoren2 == true) {
                                    player.storage.szdl_zhaoren2 = false;
                                    event.num = 6;
                                    player
                                        .chooseTarget(
                                            function (card, player, target) {
                                                var source = _status.event.source;
                                                return target != source;
                                            },
                                            '令' + get.translation(target) + '对一名其他角色造成一点伤害'
                                        )
                                        .set('ai', function (target) {
                                            return get.damageEffect(target, _status.event.source, player);
                                        })
                                        .set('source', target);
                                }
                                ('step 4');
                                if (result.bool && result.targets && result.targets.length && event.num == 6) {
                                    event.num = 0;
                                    target.line(result.targets[0], 'green');
                                    result.targets[0].damage(target);
                                }
