                                        mark(dialog, content, player) {
                                            var list = game.filterPlayer(function (target) {
                                                return target != player && target.hasSkill('szdl_newzhanshi');
                                            });
                                            if (list && list.length) return '你对' + get.translation(list) + '使用牌无距离限制';
                                        },
