                        szdl_xinxunxun: {
                            audio: 'ext:Nirvana/audio/李典:2',
                            trigger: {
                                global: 'useCardToTargeted',
                            },
                            filter(event, player) {
                                if (!event.targets || !event.targets.length) return false;
                                if (event.player != player && !event.targets.includes(player)) return false;
                                if (event.targets && event.targets.length > 1) return false;
                                return true;
                            },
                            content() {
                                'step 0';
                                var num = player.maxHp - player.hp + 1;
                                var cards = get.cards(num);
                                game.cardsGotoOrdering(cards);
                                var cardsx = get.bottomCards(num);
                                game.cardsGotoOrdering(cardsx);
                                var next = player.chooseToMove();
                                next.set('list', [
                                    ['牌堆顶', cards],
                                    ['牌堆底', cardsx],
                                ]);
                                next.set('prompt', '恂恂:点击将牌移动到牌堆顶或牌堆底');
                                next.processAI = function (list) {
                                    var cards = list[0][1],
                                        player = _status.event.player;
                                    var target = _status.currentPhase == player ? player : player.next;
                                    var att = get.sgn(get.attitude(player, target));
                                    const top = [],
                                        bottom = cards;
                                    for (const i of target.getCards('j')) {
                                        const judge = get.judge(i);
                                        bottom.sort((a, b) => (judge(b) - judge(a)) * att); //态度大于0价值高的牌放前面
                                        if (bottom.length) {
                                            top.push(bottom.shift());
                                        }
                                    }
                                    bottom.sort((a, b) => (get.value(b) - get.value(a)) * att); //态度大于0价值高的牌放前面
                                    while (bottom.length) {
                                        top.push(bottom.shift());
                                    }
                                    return [top, bottom];
                                };
                                ('step 1');
                                var top = result.moved[0];
                                var bottom = result.moved[1];
                                top.reverse();
                                for (var i = 0; i < top.length; i++) {
                                    ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
                                }
                                for (var i = 0; i < bottom.length; i++) {
                                    ui.cardPile.appendChild(bottom[i]);
                                }
                                player.popup(get.cnNumber(top.length) + '上' + get.cnNumber(bottom.length) + '下');
                                game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
                                game.updateRoundNumber();
                                ('step 2');
                                player.chooseCard('hes', player.maxHp - player.hp + 1, '恂恂:是否重铸' + get.cnNumber(player.maxHp - player.hp + 1) + '张牌？').set('ai', function (card) {
                                    val = get.value(card);
                                    return 7 - val;
                                });
                                ('step 3');
                                if (result.bool) {
                                    player.lose(result.cards, ui.discardPile);
                                    player.$throw(result.cards, 1000);
                                    game.log(player, '重铸了', result.cards);
                                    player.draw(result.cards.length).log = false;
                                }
                            },
                        },
